  function renderDeveloperProbeJob(job,id,main,actions){const output=(job.outputs||job.Outputs||[])[0]||{},collectors=output.CollectorResults||output.collectorResults||[],artifacts=job.artifacts||job.Artifacts||[];if(collectors.length){const summary=el('section','developer-probe-summary');summary.appendChild(el('h3','','環境探測摘要'));const counts=collectors.reduce((all,row)=>{const status=String(row.Status||row.status||'');all[status]=(all[status]||0)+1;return all;},{}),gaps=Object.entries(counts).filter(([status])=>['Partial','Failed','PermissionDenied','NotScheduled','Cancelled'].includes(status)).reduce((sum,[,count])=>sum+count,0);summary.appendChild(el('p','',`共 ${collectors.length} 項觀測：${counts.Completed||0} 項已取得、${counts.Partial||0} 項部分資料${gaps?`、${gaps} 項有缺口`:''}。不適用項目會分開列出，不視為已觀測。`));const list=el('ul','developer-probe-collectors');collectors.forEach(row=>{const item=el('li'),name=developerProbeCollectorName(row.Id||row.id),status=developerProbeStatus(row.Status||row.status),reason=row.ReasonCode||row.reasonCode;item.append(el('strong','',name),el('span','',status));if(reason)item.append(el('span','item-sub',String(reason)));list.appendChild(item);});summary.appendChild(list);main.appendChild(summary);}if((job.action||job.Action)!=='DeveloperProbe')return;artifacts.forEach(artifact=>{const index=Number(artifact.index),kind=String(artifact.kind||artifact.Kind||''),label=String(artifact.label||artifact.Label||''),sha=String(artifact.sha256||artifact.SHA256||''),type=String(artifact.contentType||artifact.ContentType||'');if(!Number.isInteger(index)||index<0)return;let title=null,handler=null;if(kind==='Download'&&type==='application/zip'&&/^[a-f0-9]{64}$/i.test(sha)){title=label?`下載探測 ZIP：${label}`:'下載探測 ZIP';handler=()=>downloadDeveloperProbeArtifact(id,index,artifact);}else if(kind==='Open'&&type.startsWith('text/html')&&/^[a-f0-9]{64}$/i.test(sha)){title='查看探測摘要';handler=()=>openDeveloperProbeArtifact(id,index,artifact,title);}else if(kind==='Folder'&&!sha){title='開啟探測資料夾';handler=()=>openDeveloperProbeArtifact(id,index,artifact,title);}if(!handler)return;const button=el('button','secondary-button',title);button.type='button';button.dataset.focusKey=`probe-artifact:${id}:${index}`;button.addEventListener('click',handler);actions.appendChild(button);});}
  async function openDeveloperProbeArtifact(id,index,artifact,label){if(!/^[a-f0-9-]{36}$/i.test(String(id))||!Number.isInteger(index)||index<0){fail('環境探測收據識別無法核對。');return;}try{await endpoint(`/api/jobs/${encodeURIComponent(id)}/artifacts/${index}/open`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({SHA256:String(artifact.sha256||artifact.SHA256||'')})});announce(`已要求 Windows 開啟${label}；服務端會再次核對受控材料。`);}catch(error){if(error.message!=='session expired')fail(`無法開啟${label}：${error.message}`);}}
  async function downloadDeveloperProbeArtifact(id,index,artifact){if(!/^[a-f0-9-]{36}$/i.test(String(id))||!Number.isInteger(index)||index<0||!state.token){fail('環境探測 ZIP 的工作或工作階段無法核對。');return;}const identity=viewIdentity(),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(`/api/jobs/${encodeURIComponent(id)}/artifacts/${index}`,{method:'GET',headers:{Accept:'application/zip','X-Wsm-Token':state.token},credentials:'same-origin',cache:'no-store',signal:controller.signal});if(!response.ok){let body={};try{body=await response.json();}catch(_){}throw apiError(body,response.status,'無法下載環境探測 ZIP');}if(!String(response.headers.get('content-type')||'').toLowerCase().includes('application/zip'))throw new Error('服務回傳的材料不是核准的 ZIP 格式。');const blob=await response.blob();if(identity!==viewIdentity())throw new Error('工作上下文已切換；已停止此次下載。');const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=String(artifact.label||artifact.Label||'developer-probe.zip').replace(/[\\/:*?"<>|]/g,'_');link.hidden=true;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('已從受控作業收據下載已驗證的環境探測 ZIP。');}catch(error){if(error.message!=='session expired')fail(`無法下載探測 ZIP：${error.name==='AbortError'?'下載逾時，請稍後重新連線。':error.message}`);}finally{clearTimeout(timer);}}
